# ═════════════════ 숫자총정리 10-11 (머리 선언 '아래 사항들은 전부 ★' → ★선언 레인, 의무) ═════════════════
NUMS = []
def nc(note, line, front, key, kind="T1", must=None, **kw):
    k = "숫자-" + key
    card(note, kind, front, k, "★선언", [line] if isinstance(line, int) else line, mustcontain=must, **kw)
    NUMS.append(k)
